def page(path,title,desc,body,ld=None,home=False,date=None):
    url=B+"/"+path.replace("index.html","")
    lds=[{"@context":"https://schema.org","@type":"WebSite","name":"Trends Incoming","url":B+"/","publisher":pub}] if home else []
    if ld: lds.append(ld)
    if date or (not home and not ld):
        lds.append({"@context":"https://schema.org","@type":"Article","headline":title,"description":desc,"datePublished":UPD,"dateModified":UPD,"mainEntityOfPage":url,"author":pub,"publisher":pub})
    gv='<meta name="google-site-verification" content="ezBQqKRJO61dxr5XtfUeBwFylFtxGkBcroJzRxI8vds" />\n' if home else ''
    depth=path.count("/");r="../"*depth
    h=f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
{gv}<title>{title} | Trends Incoming</title><meta name="description" content="{desc}"><meta name="robots" content="index,follow,max-image-preview:large">
<link rel="canonical" href="{url}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><meta name="twitter:card" content="summary">
<link rel="stylesheet" href="{r}style.css">{''.join('<script type="application/ld+json">'+json.dumps(x)+'</script>' for x in lds)}</head><body>
<header><nav class="nav"><a class="logo" href="{r}">Trends Incoming ⚡</a><a class="l" href="{r}games/">Games</a><a class="l" href="{r}music/grammy-nominations-2027/">Music</a><a class="l" href="{r}sports/">Sports</a><a class="l" href="{r}money/open-enrollment-2027/">Money</a></nav></header>
<main>{body}</main><footer><p>© 2026 {LLC}. All rights reserved. Trends Incoming is owned and operated by {LLC}</p>
<a href="{r}about/">About</a><a href="{r}terms/">Terms</a><a href="{r}privacy/">Privacy</a><a href="{r}disclaimer/">Disclaimer</a></footer></body></html>"""
    fp=path; os.makedirs(os.path.dirname(fp) or ".",exist_ok=True); open(fp,"w").write(h); return url
def src(lst): return '<h2>Sources</h2><ul class="src">'+"".join(f'<li><a href="{u}" rel="noopener">{t}</a></li>' for t,u in lst)+f'</ul><p class="tag">Last fact-checked {UPD}. Dates can change; always confirm with the official source.</p>'
